import {enrichment} from './enrichment-data.js';
import { resourceCatalog } from './resources-data.js';
import { guides } from './learning-content.js';
import { visualMarkup, bindVisual } from './visual-lessons.js';
export {resourceCatalog};
const P=(fr,en)=>[fr,en];
const E=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const courses={seconde:P('Seconde','Seconde'),premiere:P('Première spécialité','Première · mathematics specialty'),terminale:P('Terminale spécialité','Terminale · mathematics specialty'),stmg:P('Terminale STMG','Terminale STMG')};
const kinds={chapter:P('Chapitre élève · cours, activités et exercices','Student chapter · lessons, activities and exercises'),teacher:P('Édition professeur · corrections et conseils','Teacher edition · solutions and guidance'),fluency:P('Automatismes · fiche élève','Fluency · student worksheet'),'fluency-solutions':P('Automatismes · corrigé','Fluency · solutions')};
const tabs={understand:P('Comprendre','Understand'),experiment:P('Expérimenter','Experiment'),practice:P('S’entraîner','Practise'),documents:P('Documents','Documents')};
let filter='all',query='';
const normalize=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
export function matchingChapters(course,search){const q=normalize(search.trim());return resourceCatalog.chapters.filter(c=>(course==='all'||c.course===course)&&(!q||normalize([...c.title,c.course,c.topic].join(' ')).includes(q)));}
export function matchingSupplements(course,search){const q=normalize(search.trim());return resourceCatalog.supplements.filter(c=>(course==='all'||c.course===course)&&(!q||normalize([...c.title,c.course,c.kind].join(' ')).includes(q)));}
function supplementCards(items,t){return items.length?`<div class="course-supplements"><h3>${t(P('Banques d’exercices & préparation','Exercise banks & preparation'))}</h3>${items.map(c=>`<details class="supplement-card"><summary>${E(t(c.title))}</summary>${fileLink(c.files[0],t(P('Version élève','Student version')))}<details><summary>${t(P('Version professeur / corrections','Teacher version / solutions'))}</summary>${fileLink(c.files[1],t(P('Ouvrir la version professeur','Open the teacher version')))}<p class="document-meta">${t(P('Les versions peuvent inclure des variantes différentes : compare les énoncés.','The editions may contain different variants: compare the questions.'))}</p></details></details>`).join('')}</div>`:'';}
function workshopCards(t){const q=normalize(query.trim());const found=enrichment.filter(p=>(filter==='all'||filter==='explorations')&&(!q||normalize([...p.title,...p.prerequisites,...p.level].join(' ')).includes(q)));return found.length?`<section class="course-group enrichment-group"><div class="course-title"><h2>${t(P('Ateliers & approfondissements','Workshops & enrichment'))}</h2><span>${found.length} · FR / EN</span></div><p>${t(P('Une méthode, quatre exercices progressifs et un problème de synthèse, avec solutions séparées.','A method, four progressive exercises and a synthesis problem, with separate solutions.'))}</p><div class="chapter-grid">${found.map(p=>`<a class="chapter-card enrichment-card" href="#library/explore-${p.id}"><span class="chapter-number">${String(enrichment.indexOf(p)+1).padStart(2,'0')}</span><span><h3>${E(t(p.title))}</h3><span class="chapter-types">${E(t(p.level))}</span></span><span class="chapter-open">${t(P('Explorer','Explore'))}</span></a>`).join('')}</div></section>`:'';}
function cards(t){const found=matchingChapters(filter,query),extra=matchingSupplements(filter,query);return `<p class="resource-count" role="status">${found.length} ${t(P('chapitres','chapters'))} · ${extra.length} ${t(P('ressources de préparation','preparation resources'))}</p>${Object.entries(courses).filter(([id])=>[...found,...extra].some(c=>c.course===id)).map(([id,title])=>`<section class="course-group"><div class="course-title"><h2>${E(t(title))}</h2><span>2026–2027</span></div><div class="chapter-grid">${found.filter(c=>c.course===id).map(c=>`<a class="chapter-card" href="#chapter/${c.id}"><span class="chapter-number">${String(c.number).padStart(2,'0')}</span><span><h3>${E(t(c.title))}</h3><span class="chapter-types">${t(P('Cours · exercices · corrigés','Lessons · exercises · solutions'))}${c.files.some(f=>f.kind==='fluency')?' · '+t(P('Automatismes','Fluency')):''}</span></span><span class="chapter-open">${t(P('Ouvrir','Open'))}</span></a>`).join('')}</div>${supplementCards(extra.filter(c=>c.course===id),t)}</section>`).join('')}${workshopCards(t)}${found.length||extra.length||workshopCards(t)?'':`<div class="resource-empty"><p>${t(P('Aucune ressource ne correspond à cette recherche.','No resources match this search.'))}</p><button data-clear-search>${t(P('Effacer les filtres','Clear filters'))}</button></div>`}`;}
export function libraryPage(t){documentLanguage=t(P('fr','en'));return `<main id="main" tabindex="-1" class="page resource-page"><div class="resource-heading"><div><span class="eyebrow">${t(P('TES COURS, EN UN SEUL ENDROIT','YOUR COURSES, IN ONE PLACE'))}</span><h1>${t(P('Cours & exercices','Lessons & exercises'))}</h1></div><span class="resource-total">47 ${t(P('chapitres','chapters'))}<small>4 ${t(P('niveaux','courses'))} · 12 ${t(P('ateliers','workshops'))}</small></span></div><p class="library-intro">${t(P('Choisis un chapitre. Comprends l’idée, fais varier le graphique, puis résous les exercices.','Choose a chapter. Understand the idea, change the diagram, then solve the exercises.'))}</p><div class="resource-filters"><label>${t(P('Rechercher un chapitre','Find a chapter'))}<input id="resource-search" type="search" value="${E(query)}" placeholder="${t(P('Suites, logarithme, probabilités…','Sequences, logarithm, probability…'))}"></label><label>${t(P('Niveau','Course'))}<select id="resource-course"><option value="all">${t(P('Tous les niveaux','All courses'))}</option><option value="explorations" ${filter==='explorations'?'selected':''}>${t(P('Ateliers & approfondissements','Workshops & enrichment'))}</option>${Object.entries(courses).map(([id,label])=>`<option value="${id}" ${filter===id?'selected':''}>${E(t(label))}</option>`).join('')}</select></label></div><p class="catalogue-link"><a href="#workshop/quadratic">${t(P("Trinôme · présenter et explorer en cinq étapes","Quadratics · present and explore in five stages"))}</a> · <a href="#library">${t(P("Tous les fichiers · filtrer par type, langue et parcours","All files · filter by type, language and pathway"))}</a></p><div id="resource-results">${cards(t)}</div><details class="resource-origin"><summary>${t(P('D’où viennent ces ressources ?','Where do these resources come from?'))}</summary><p>${t(P('Les livrets sont disponibles en français et en anglais. Les guides essentiels et graphiques accompagnent chaque chapitre.','The booklets are available in French and English. Essential guides and diagrams accompany each chapter.'))}</p><p>${t(P('Les documents correspondent à l’édition du 8 octobre 2026.','The documents are from the 8 October 2026 edition.'))}</p><p>${t(P('Inspiration : simulations de Javalab et parcours cours–exercices de Mathoutils. Les animations de ce site sont interactives et calculées dans le navigateur.','Inspiration: Javalab simulations and Mathoutils lesson–exercise pathways. This site’s animations are interactive and computed in your browser.'))}</p><a href="https://javalab.org/en/" target="_blank" rel="noopener">Javalab</a> · <a href="https://www.mathoutils.fr/" target="_blank" rel="noopener">Mathoutils</a></details></main>`;}
export function bindLibrary(t){const results=document.querySelector('#resource-results');const paint=()=>{results.innerHTML=cards(t);const clear=results.querySelector('[data-clear-search]');clear?.addEventListener('click',()=>{filter='all';query='';document.querySelector('#resource-search').value='';document.querySelector('#resource-course').value='all';paint();});};document.querySelector('#resource-search').addEventListener('input',e=>{query=e.target.value;paint();});document.querySelector('#resource-course').addEventListener('change',e=>{filter=e.target.value;paint();});paint();}
let documentLanguage='fr';
const fileLink=(f,label,page=1)=>`<a class="document-link" href="./${documentLanguage==='en'?f.englishPath:f.path}#page=${page}" target="_blank" rel="noopener">${E(label)} <span>PDF · FR / EN · ${f.pages} p.</span></a>`;
function documentCards(c,t){return c.files.map(f=>{const source=resourceCatalog.sources.find(s=>s.name===f.source);const teacher=f.kind==='teacher'||f.kind==='fluency-solutions';const links=Object.entries(f.sections||{}).filter(([k])=>['lesson','practice','problem','quiz'].includes(k)).map(([k,p])=>fileLink(f,t({lesson:P('Cours / activités','Lessons / activities'),practice:P('Exercices','Exercises'),problem:P('Problèmes','Problems'),quiz:P('QCM','Multiple choice')}[k]),p)).join('');const label=t(kinds[f.kind])+(f.title?' · '+t(f.title):'');const body=`${fileLink(f,label)}${links?`<div class="section-links">${links}</div>`:''}<p class="document-meta">${t(P('Pages du document source','Source document pages'))} ${f.start}–${f.end} · ${t(P('Modifié le','Modified'))} ${source.modified.slice(0,10)}</p>`;return teacher?`<details class="document-card"><summary>${E(label)}</summary>${body}</details>`:`<article class="document-card">${body}</article>`;}).join('');}
function sourcePractice(c,t){const f=c.files.find(f=>f.kind==='chapter');return `<div class="source-practice"><h2>${t(P('Poursuivre dans ton livret','Continue in your booklet'))}</h2><p>${t(P('Le chapitre complet contient les activités et les exercices de ton niveau. Certaines pages mêlent cours et entraînement.','The full chapter contains activities and exercises for your course. Some pages combine lessons and practice.'))}</p>${fileLink(f,t(P('Ouvrir les exercices du chapitre','Open the chapter exercises')),f.sections?.practice||1)}<details><summary>${t(P('Consulter la version professeur après avoir cherché','Read the teacher version after trying'))}</summary>${fileLink(c.files.find(f=>f.kind==='teacher'),t(P('Corrections et conseils','Solutions and guidance')))}${c.course==='premiere'?`<p>${t(P('Attention : le PDF élève du 18 septembre est plus récent que la version professeur du 10 septembre. Compare les énoncés avant d’utiliser une correction.','Note: the student PDF from 18 September is newer than the teacher version from 10 September. Compare the questions before using a solution.'))}</p>`:''}</details></div>`;}
export function chapterPage(id,tab,t,labs){documentLanguage=t(P('fr','en'));const c=resourceCatalog.chapters.find(c=>c.id===id),g=guides[c.topic];tab=Object.hasOwn(tabs,tab)?tab:'understand';const lab=g.lab?labs.find(l=>l.id===g.lab):null;const nearby=resourceCatalog.chapters.filter(x=>x.course===c.course);const prev=nearby.find(x=>x.number===c.number-1),next=nearby.find(x=>x.number===c.number+1);const visual=visualMarkup(g.scene,t);let body='';
 if(tab==='understand')body=`<div class="chapter-workbench"><article class="companion"><span class="eyebrow">${t(P('GUIDE ESSENTIEL','ESSENTIAL GUIDE'))}</span><h2>${t(P('L’idée à retenir','The central idea'))}</h2><p class="central-idea">${E(t(g.idea))}</p><ul class="lesson-facts">${g.facts.map(f=>`<li>${E(t(f))}</li>`).join('')}</ul><section class="worked-example"><h3>${t(P('Exemple expliqué','Worked example'))}</h3><p>${E(t(g.example.question))}</p><ol>${g.example.steps.map(s=>`<li>${E(t(s))}</li>`).join('')}</ol></section><p class="companion-scope">${t(P('Ce guide met en lumière une idée centrale du chapitre. Pour l’ensemble des notions, consulte le livret complet dans Documents.','This guide highlights one central idea from the chapter. For the full set of topics, read the complete booklet in Documents.'))}</p></article>${visual}</div>`;
 if(tab==='experiment')body=`<div class="experiment-chapter">${visual}<aside class="experiment-prompts"><h2>${t(P('Prédire, observer, expliquer','Predict, observe, explain'))}</h2><ol><li>${t(P('Avant de déplacer le curseur, prédis ce qui va changer.','Before moving the slider, predict what will change.'))}</li><li>${t(P('Teste deux valeurs très différentes. Lis aussi les valeurs du modèle.','Test two very different values. Read the model values too.'))}</li><li>${t(P('Explique ce qui reste invariant avec une équation ou une propriété.','Explain what stays invariant using an equation or a property.'))}</li></ol>${lab?`<a class="lab-jump" href="#lab/${lab.id}">${t(P('Explorer librement :','Explore freely:'))} ${E(t(lab.title))}</a><p>${t(P('Dans le laboratoire, les points se déplacent directement à la souris, au toucher ou au clavier.','In the laboratory, move the points directly using a mouse, touch or keyboard.'))}</p>`:''}</aside></div>`;
 if(tab==='practice')body=`<div class="practice-layout"><article class="practice-card"><span class="eyebrow">${t(P('À TOI DE JOUER','YOUR TURN'))}</span><h2>${t(P('Transférer l’idée','Apply the idea'))}</h2><p>${E(t(g.practice.question))}</p><details><summary>${t(P('Un indice','A hint'))}</summary><p>${E(t(g.practice.hint))}</p></details><details><summary>${t(P('Comparer avec la solution','Compare with the solution'))}</summary><p>${E(t(g.practice.solution))}</p></details></article>${sourcePractice(c,t)}</div>`;
 if(tab==='documents')body=`<p class="document-intro">${t(P('Documents en français et en anglais, téléchargeables chapitre par chapitre. La langue du site détermine celle du PDF. Les liens de section sont des repères : une page peut contenir plusieurs types de contenu.','French and English documents, available chapter by chapter. The site language selects the PDF language. Section links are pointers: a page may contain several types of content.'))}</p>${c.course==='premiere'?`<p class="edition-note">${t(P('Le livret élève est daté du 18 septembre 2026 ; le livret professeur du 10 septembre. Vérifie que l’énoncé correspond avant de consulter sa correction.','The student booklet is dated 18 September 2026; the teacher booklet 10 September. Check that the question matches before consulting its solution.'))}</p>`:''}<p><a class="lab-jump" href="#library/${c.id}">${t(P("Notes, exercices et problèmes en fichiers séparés","Notes, exercises and problems as separate files"))}</a></p><div class="document-grid">${documentCards(c,t)}</div>`;
 return `<main id="main" tabindex="-1" class="page chapter-page"><a class="back-library" href="#resources">${t(P('Tous les chapitres','All chapters'))}</a><div class="chapter-heading"><span class="eyebrow">${E(t(courses[c.course]))} · ${t(P('CHAPITRE','CHAPTER'))} ${c.number}</span><h1>${E(t(c.title))}</h1></div><nav class="chapter-tabs" aria-label="${t(P('Sections du chapitre','Chapter sections'))}">${Object.entries(tabs).map(([key,title])=>`<a href="#chapter/${c.id}/${key}" ${key===tab?'aria-current="page"':''}>${E(t(title))}</a>`).join('')}</nav>${body}<nav class="chapter-next" aria-label="${t(P('Ordre des chapitres','Chapter order'))}">${prev?`<a href="#chapter/${prev.id}">${t(P('Précédent','Previous'))} · ${E(t(prev.title))}</a>`:'<span></span>'}${next?`<a href="#chapter/${next.id}">${t(P('Suivant','Next'))} · ${E(t(next.title))}</a>`:''}</nav></main>`;
}
export function bindChapter(id,t,fmt){const c=resourceCatalog.chapters.find(c=>c.id===id);const root=document.querySelector('.visual-lesson');return root?bindVisual(root,guides[c.topic].scene,t,fmt):()=>{};}
export function relatedChapters(labId,t){const related=resourceCatalog.chapters.filter(c=>guides[c.topic]?.lab===labId);return related.length?`<details class="related-chapters"><summary>${t(P('Cours et exercices liés','Related lessons and exercises'))}</summary><div>${related.map(c=>`<a href="#chapter/${c.id}">${E(t(courses[c.course]))} · ${E(t(c.title))}</a>`).join('')}</div></details>`:'';}
